orders = [{"customer": 1, "amount": 500}, {"customer": 1, "amount": 300}]

def revenue_by_customer(rows):
    totals = {}
    for row in rows:
        customer = row["customer"]
        totals[customer] = totals.get(customer, 0) + row["amount"]
    return totals

print(revenue_by_customer(orders))  # {1: 800}

